import numpy as np
import matplotlib.pyplot as plt
from scipy import signal

def closed(num, den, cn, cd):
    n=np.polymul(num,cn)
    d=np.polyadd(np.polymul(den,cd),n)
    return signal.TransferFunction(n,d)

def curve(sys, end=10, count=501):
    return signal.step(sys,T=np.linspace(0,end,count))

